var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene(); var map=s.GetRootGameObjects().First(g=>g.name.StartsWith("Blackpine"));
return new {map=map.GetComponentsInChildren<Transform>().Select(t=>new{name=t.name,pos=t.position.ToString(),scale=t.lossyScale.ToString(),bounds=t.GetComponent<Renderer>()==null?"":t.GetComponent<Renderer>().bounds.ToString(),mesh=t.GetComponent<MeshFilter>()==null?"":UnityEditor.AssetDatabase.GetAssetPath(t.GetComponent<MeshFilter>().sharedMesh),components=t.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray(),bases=Resources.FindObjectsOfTypeAll<Base>().Where(b=>b.gameObject.scene==s).Select(b=>new{name=b.name,pos=b.transform.position.ToString(),json=UnityEditor.EditorJsonUtility.ToJson(b)}).ToArray(),wave=UnityEditor.EditorJsonUtility.ToJson(UnityEngine.Object.FindObjectOfType<WaveManager>()),camera=UnityEditor.EditorJsonUtility.ToJson(Camera.main),models=new[]{"Assets/ArcherTower.fbx","Assets/MagicV1.fbx","Assets/UnityTower.fbx"}.Select(p=>new{path=p,children=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(p).GetComponentsInChildren<Renderer>().Select(r=>new{name=r.name,bounds=r.bounds.ToString()}).ToArray()}).ToArray()};
